	"Use the Monitor tool to stream events from a background process: each stdout line is a notification. For one-shot wait-until-done, use Bash with run_in_background instead. In Pi, monitor_start is the Monitor tool. Set triggerOnOutput:true for event streams and emit exactly one actionable stdout line per event; lines within 200ms batch into one notification. Do not monitor raw noisy output with output wakes enabled. Only stdout can be an event stream; stderr is logged but never wakes — merge with 2>&1 when failures must reach your filter. Every pipe stage must flush per line (grep --line-buffered, awk fflush(); `| head -N` buffers and breaks). Cover terminal failure states (Error|Traceback|FAILED|Killed) because silence looks identical to still running. Monitors that wake the agent too often are automatically stopped; restart with a tighter filter. Returns a monitorId; bounded log slices via monitor_read, stop via monitor_stop.",
parameters: objectSchema(
	{
		command: stringSchema("Shell command to monitor via /bin/sh -c. Each stdout line is an event; exit ends the watch. Keep polling intervals inside the command (30s+ for remote APIs, 0.5-1s for local checks) and make poll loops failure-tolerant (`curl ... || true`)."),
		description: stringSchema("Short specific label shown in every notification, e.g. 'errors in deploy.log', 'PR 83 CI checks' — not 'watching logs'."),
		cwd: stringSchema("Working directory (default: session cwd)"),
		triggerOnOutput: booleanSchema("Wake/steer the agent when new stdout arrives (default true — each stdout event line is a notification). Set false only for manual-inspection streams."),
		triggerOnExit: booleanSchema("Wake the agent when the process exits. Default true; set false for pure tails/watchers that are expected to run until stopped."),
		maxWakeups: numberSchema("Maximum output-triggered agent wakeups before the monitor is automatically stopped (default 20, max 100). Does not affect final exit wake."),
		maxRuntimeSeconds: numberSchema("Maximum runtime before the monitor is stopped (default 3600, max 43200; persistent monitors default to 86400 and allow up to 259200)."),
		persistent: booleanSchema("Run as a long session-length watch (PR monitoring, log tails). Still bounded by an absolute safety ceiling — default 24h, max 72h via maxRuntimeSeconds — so a stuck or abandoned watch can't poll forever. Stop with monitor_stop."),
	},
	["command", "description"],
),
async execute(_id, rawParams, _signal, _onUpdate, ctx) {
	const params = rawParams as MonitorStartParams;
	const id = newId();
	const maxWakeups = clamp(params.maxWakeups, DEFAULT_MAX_OUTPUT_WAKEUPS, MAX_OUTPUT_WAKEUPS);
	// Persistent watches keep their session binding but get a long absolute
	// safety ceiling (24h default, 72h max) instead of running uncapped.
	const maxRuntimeSeconds = params.persistent
		? clamp(params.maxRuntimeSeconds, PERSISTENT_DEFAULT_RUNTIME_SECONDS, PERSISTENT_MAX_RUNTIME_SECONDS)
		: clamp(params.maxRuntimeSeconds, DEFAULT_MAX_RUNTIME_SECONDS, MAX_RUNTIME_SECONDS);
	const m: MonitorState = {
		id,
		description: params.description,
		command: params.command,
		cwd: params.cwd ?? ctx.cwd,
		status: "running",
		startedAt: Date.now(),
		proc: null,
		recentLines: [],
		totalLines: 0,
		pendingLines: [],
		logPath: logPathFor(id),
		suppressedDuplicateLines: 0,
		// Claude Code Monitor parity: stdout is the event stream by default.
		// Use Bash run_in_background for one-shot wait-until-done.
		triggerOnOutput: params.triggerOnOutput ?? true,
		triggerOnExit: params.triggerOnExit ?? true,
		persistent: params.persistent ?? false,
		wakeCount: 0,
		maxWakeups,
		maxRuntimeMs: maxRuntimeSeconds * 1000,
		outputBytes: 0,
	};
	monitors.set(id, m);

	let proc: ChildProcess;
	try {
		proc = startMonitorProcess(params.command, m.cwd);
	} catch (cause) {
		m.status = "failed";
		m.endedAt = Date.now();
		updateFooter(ctx);
		throw toError(cause);
	}
	m.proc = proc;
	// unref so the monitor process group doesn't keep Node alive
	proc.unref();
	// Every monitor — persistent included — gets an absolute runtime ceiling so
	// an abandoned or silently-stuck watch can't poll forever. Non-persistent:
	// short cap (default 1h). Persistent (CC-style session-length watch): a long
	// safety ceiling (default 24h) on top of the session binding; session_shutdown
	// still kills all monitors first. On hit, wake (if triggerOnExit) with a
	// re-arm hint so the silence becomes actionable instead of infinite.
	m.timeoutTimer = setTimeout(() => {
		if (m.status !== "running") return;
		m.outputWakeDisabledReason = m.persistent
			? `persistent safety ceiling ${maxRuntimeSeconds}s reached`
			: `maxRuntimeSeconds ${maxRuntimeSeconds} reached`;
		killMonitor(m);
		safeSend(
			pi,
			{
				customType: "monitor-event",
				content: singleLineDisplay(
					m.persistent
						? `[monitor ${m.description}] stopped after persistent safety ceiling ${maxRuntimeSeconds}s — ${m.totalLines} line(s), ${m.wakeCount} wakeup(s). Re-arm monitor_start if the watch is still needed. Log: ${m.id}`
						: `[monitor ${m.description}] stopped after maxRuntimeSeconds ${maxRuntimeSeconds}. Log: ${m.id}`,
				),
				display: true,
				details: { monitorId: m.id, description: m.description, event: "stopped", status: m.status, reason: m.outputWakeDisabledReason, logPath: m.logPath, persistent: m.persistent },
			},
			m.triggerOnExit ? { deliverAs: "steer", wakeOnIdle: true } : undefined,
		);
		safeFooter(state.activeCtx);
	}, maxRuntimeSeconds * 1000);
	m.timeoutTimer?.unref?.();

	proc.stdout?.on("data", (c: Buffer) => {
		if (state.runtimeStale) return;
		ingest(pi, m, c);
	});
	proc.stderr?.on("data", (c: Buffer) => {
		if (state.runtimeStale) return;
		// stderr is logged but never queues a wake (CC parity).
		ingest(pi, m, c, false);
	});
	proc.on("exit", (code, signal) => {
		if (m.timeoutTimer) {
			clearTimeout(m.timeoutTimer);
			m.timeoutTimer = undefined;
		}
		// If killMonitor already marked this killed, suppress stale notifications
		if (m.status === "killed") {
			safeFooter(state.activeCtx);
			return;
		}
		m.status = signal ? "killed" : code === 0 ? "exited" : "failed";
		m.exitCode = code;
		m.signal = signal;
		m.endedAt = Date.now();
		// If the runtime is dead (session reloaded / forked / disposed while a
		// detached monitor was still running), don't touch pi/ctx — that would
		// throw "extension ctx is stale" out of the ChildProcess emit path and
		// crash pi.
		if (state.runtimeStale) return;
		flushNotify(pi, m);
		safeSend(
			pi,
			{
				customType: "monitor-event",
				content: singleLineDisplay(`Monitor ${m.status}: ${m.description}${code != null ? ` (code ${code})` : ""}${signal ? ` (signal ${signal})` : ""}`),
				display: true,
				details: { monitorId: m.id, description: m.description, event: "exit", status: m.status, exitCode: code, signal, logPath: m.logPath, totalLines: m.totalLines, outputBytes: m.outputBytes, wakeCount: m.wakeCount },
			},
			m.triggerOnExit ? { deliverAs: "steer", wakeOnIdle: true } : undefined,
		);
		safeFooter(state.activeCtx);
	});
	proc.on("error", (err) => {
		m.status = "failed";
		m.endedAt = Date.now();
		if (m.timeoutTimer) {
			clearTimeout(m.timeoutTimer);
			m.timeoutTimer = undefined;
		}
		if (state.runtimeStale) return;
		safeFooter(state.activeCtx);
		safeSend(
			pi,
			{
				customType: "monitor-event",
				content: singleLineDisplay(`Monitor failed: ${m.description} — ${err.message}`),
				display: true,
				details: { monitorId: m.id, description: m.description, event: "error", status: "failed", error: err.message },
			},
			// Same rationale as the exit handler: wake an idle agent so process
			// startup failures don't sit silently until the next user prompt.
			{ deliverAs: "steer", wakeOnIdle: true },
		);
	});

	updateFooter(ctx);
	if (m.triggerOnExit) {
		getGoalWaitRegistry().requestWait(
			{
				kind: "monitor",
				ref: m.id,

			);
		}
		return {
			content: [
				{
					type: "text",
					text: `Monitor started · task ${id} · ${m.persistent ? `persistent · safety cap ${maxRuntimeSeconds}s` : `timeout ${maxRuntimeSeconds}s`}`,
				},
			],
			details: {
				monitorId: id,
				description: params.description,
				command: params.command,
				cwd: m.cwd,
				triggerOnOutput: m.triggerOnOutput,
				triggerOnExit: m.triggerOnExit,
				persistent: m.persistent,
				maxWakeups,
				maxRuntimeSeconds,
			},
		};
	},
});

