import assert from "node:assert/strict";
import { createJiti } from "jiti";

const jiti = createJiti(import.meta.url, { interopDefault: true, fsCache: false });
const mod = await jiti.import("./index.ts");
const factory = mod.default ?? mod;

const pathological = "\u001b[31m" + "x".repeat(260) + "\u001b[0m\n" + "/Users/luke/Projects/personal/my-pi/" + "deep/".repeat(30) + "artifact.log";
const display = mod.singleLineDisplay(pathological);
assert(!display.includes("\n"), "monitor display summaries never contain embedded newlines");
assert(!display.includes("\u001b"), "monitor display summaries strip ANSI/control sequences");
assert(display.length <= 220, "monitor display summaries are capped for narrow TUI cards");

const handlers = {};
const tools = [];
const panes = new Map();
const footers = new Map();
let shownPane;
const renderers = {};
const stubApi = {
  on: (event, handler) => {
    handlers[event] = handler;
  },
  registerTool: (definition) => {
    tools.push(definition);
  },
  registerCommand: () => {},
  registerShortcut: () => {},
  registerCustomEditor: () => {},
  registerMessageRenderer: (type, fn) => {
    renderers[type] = fn;
  },
  registerMainPane: (id, factory) => panes.set(id, factory),
  registerFooter: (id, spec) => footers.set(id, spec),
  showMainPane: (id) => { shownPane = id; },
};

factory(stubApi);

assert.equal(typeof handlers.session_start, "function", "session_start handler registered");
assert.equal(typeof handlers.session_shutdown, "function", "session_shutdown handler registered");
assert.deepEqual(
  tools.map((tool) => tool.name),
  ["monitor_start", "monitor_status", "monitor_read", "monitor_stop", "monitor_list"],
  "monitor tool set registered",
);
assert(tools.every((tool) => tool.deferLoading === true), "monitor tools are native-deferred");
assert.equal(panes.has("monitors"), true, "monitor main pane registered when B5 hooks exist");
assert.equal(footers.has("monitors"), true, "monitor footer registered when B5 hooks exist");
assert.equal(footers.get("monitors").visible(), false, "monitor footer starts hidden with no active monitors");

// CC-style Monitor surface: stdout-event wakes by default + stderr quiet.
// One-shot wait-until-done belongs to Bash run_in_background.
const start = tools.find((tool) => tool.name === "monitor_start");
const params = start.parameters.properties;
assert.ok(params.persistent, "monitor_start exposes persistent (session-length watch)");
assert.match(
  params.triggerOnOutput.description,
  /default true/,
  "output wakes are documented as the Monitor default",
);
assert.match(
  start.description,
  /For one-shot wait-until-done, use Bash with run_in_background instead/,
  "description routes completion-only waits to Bash run_in_background",
);
assert.match(
  start.description,
  /each stdout line is a notification/s,
  "description documents Monitor as a stdout event stream",
);
assert.match(start.description, /stderr is logged but never wakes/, "stderr is not an event stream");

// Behavior: start a real short-lived monitor and verify Monitor stdout-event defaults + stderr split.
const sent = [];
stubApi.sendMessage = (message, options) => sent.push({ message, options });
const ctx = { cwd: process.cwd(), hasUI: false, ui: { notify: () => {}, setStatus: () => {} } };
const started = await start.execute("t1", { command: "echo out-line; echo err-line 1>&2", description: "parity probe" }, undefined, undefined, ctx);
assert.equal(footers.get("monitors").visible(), true, "monitor footer appears while a monitor is active");
assert.match(footers.get("monitors").render({ theme: { fg: (_color, value) => value }, selected: true, width: 120 }), /▶ 1 mon · enter monitors/, "monitor footer is selectable and discoverable");
footers.get("monitors").onActivate({ close: () => {} });
assert.equal(shownPane, "monitors", "monitor footer opens the monitors main pane");
assert.equal(started.details.triggerOnOutput, true, "triggerOnOutput defaults true (Monitor event stream)");
assert.equal(started.details.persistent, false, "persistent defaults false");
await new Promise((resolve) => setTimeout(resolve, 600));
const wake = sent.find((s) => s.options?.deliverAs === "steer" && String(s.message.content).includes("out-line"));
assert.ok(wake, `stdout line produced a steer wake; got: ${JSON.stringify(sent.map((s) => s.message.content))}`);
assert(!String(wake.message.content).includes("\n"), "monitor wake cards are single-line summaries");
assert(String(wake.message.content).length <= 220, "monitor wake cards are capped for TUI rendering");
assert.ok(
  !sent.some((s) => String(s.message.content).includes("err-line")),
  "stderr lines never wake the agent",
);
const status = tools.find((tool) => tool.name === "monitor_status");
const probe = await status.execute("t2", { monitorId: started.details.monitorId });
assert.match(probe.content[0].text, /err-line/, "stderr still lands in the log/preview");

sent.length = 0;
const eventStarted = await start.execute("t3", { command: "echo event-line", description: "event probe", triggerOnOutput: true }, undefined, undefined, ctx);
await new Promise((resolve) => setTimeout(resolve, 600));
const eventWake = sent.find((s) => s.options?.deliverAs === "steer" && String(s.message.content).includes("event-line"));
assert.ok(eventWake, `explicit triggerOnOutput wakes for filtered events; monitor ${eventStarted.details.monitorId}; got: ${JSON.stringify(sent.map((s) => s.message.content))}`);

// Persistent monitors get a finite long safety ceiling instead of running
// uncapped. CC leaves persistent at timeoutMs:0; we add a 24h default ceiling
// (72h hard max, overridable via maxRuntimeSeconds), still session-bound. This
// guards the failure mode where a stuck/abandoned persistent watch polls forever
// and "silence looks identical to still running".
const persistentStarted = await start.execute("t4", { command: "true", description: "persistent ceiling probe", persistent: true }, undefined, undefined, ctx);
assert.equal(persistentStarted.details.persistent, true, "persistent flag set");
assert.equal(persistentStarted.details.maxRuntimeSeconds, 24 * 60 * 60, "persistent monitors default to a finite 24h safety ceiling, not null/uncapped");
assert.match(persistentStarted.content[0].text, /persistent · safety cap 86400s/, "start result advertises the persistent safety cap");
const persistentOverride = await start.execute("t5", { command: "true", description: "persistent override", persistent: true, maxRuntimeSeconds: 100000 }, undefined, undefined, ctx);
assert.equal(persistentOverride.details.maxRuntimeSeconds, 100000, "persistent honors an explicit maxRuntimeSeconds override");
const persistentCapped = await start.execute("t6", { command: "true", description: "persistent capped", persistent: true, maxRuntimeSeconds: 999999 }, undefined, undefined, ctx);
assert.equal(persistentCapped.details.maxRuntimeSeconds, 72 * 60 * 60, "persistent maxRuntimeSeconds clamps to the 72h hard ceiling");

handlers.session_shutdown();

// Clean feed card: structured monitor-event details render as a glyph + bold
// description headline with a dim meta footer, not a raw content dump. The
// renderer lazy-loads pi-tui (no eager import), so let that load settle first.
assert.equal(typeof renderers["monitor-event"], "function", "monitor-event renderer registered");
await new Promise((resolve) => setTimeout(resolve, 200));
const theme = { fg: (k, t) => `<${k}>${t}`, bold: (t) => `**${t}**` };
const renderToText = (component) =>
  (component.render ? component.render(80) : [String(component)]).join("\n");
const card = renderToText(
  renderers["monitor-event"](
    {
      customType: "monitor-event",
      content: "[monitor parity probe] 1 new line",
      details: { monitorId: "m1", description: "parity probe", event: "output", tail: ["out-line"], status: "running", logPath: "/x.log", totalLines: 1, wakeCount: 1, maxWakeups: 20 },
    },
    {},
    theme,
  ),
);
assert.match(card, /\*\*parity probe\*\*/, "renders the bold description headline");
assert.match(card, /running/, "renders the status");
assert.match(card, /out-line/, "renders the output tail");
assert.match(card, /wake 1\/20/, "renders the dim meta footer");
assert.doesNotMatch(card, /\[monitor parity probe\]/, "does not dump the raw steer content");
// Messages without structured details fall back to the raw content line.
const legacy = renderToText(
  renderers["monitor-event"]({ customType: "monitor-event", content: "legacy line", details: undefined }, {}, theme),
);
assert.match(legacy, /legacy line/, "falls back to raw content when details are absent");

console.log("✅ pi-monitor smoke test passed");

